      "choice": "v1",
      "reason": "Le point 1.10, page 1, prévoit le second projet SP-2026-14 concernant notamment la zone CH-217, et la page 12 confirme la modification des contributions pour parcs."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "Le point 1.11, page 1, inscrit explicitement le second projet SP-2026-15 relatif à la grille des spécifications de la zone V-802."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "Le règlement 1470-2026 figure au point 1.12, page 1, et son calendrier en page 17 indique une adoption prévue le 2 juin 2026."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "Le règlement de zonage 1471-2026 figure au point 1.13, page 1, et son calendrier en page 28 confirme l’adoption prévue le 2 juin 2026."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "Le règlement 1472-2026 relatif aux permis et certificats est inscrit au point 1.14, page 1, avec une adoption prévue le 2 juin 2026 au calendrier de la page 41."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "Le règlement 1473-2026 modifiant la réglementation des PIIA est inscrit au point 1.15, page 1, et la page 42 indique son adoption prévue le 2 juin 2026."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "Le point 1.16, page 2, prévoit expressément une demande de prolongation du délai de conformité aux normes de lotissement agricole découlant du règlement 399-25."
    },
    {
      "item": "i08",
      "choice": "v1",
      "reason": "Le point 1.20, page 2, prévoit une demande de modification du règlement 188-07 visant à réduire l’aire d’affectation « Conservation », sans attester une modification acquise."
    },
    {
      "item": "i09",
      "choice": "absent",
      "reason": "Le point 6.3, page 2, inscrit bien la servitude sur le lot 4 037 185, mais ne précise aucune adoption ou autorisation, même prévue, permettant de valider l’étape « adoption » proposée."
    },
    {
      "item": "i10",
      "choice": "v1",
      "reason": "Le point 9.1, page 3, inscrit la demande de PIIA au 799, rue de New Glasgow, ce qui atteste son examen prévu et non son approbation."
    },
    {
      "item": "i11",
      "choice": "v1",
      "reason": "Le point 9.2, page 3, prévoit le traitement d’une dérogation mineure au 537, chemin de l’Achigan Ouest, sans en donner l’issue."
    },
    {
      "item": "i12",
      "choice": "v1",
      "reason": "Le point 9.3, page 3, prévoit le traitement d’une dérogation mineure au 318-318 A, chemin Abercrombie, sans attester de décision."
    }
  ]
}
